  226: /// A re-check of one recorded pid (`Test-UnverifiedProcess` / `Test-RecordedProcess`):
  227: /// `{ Alive; How }`.
  228: #[derive(Debug, Clone, PartialEq, Eq)]
  229: pub struct Verdict {
  230:     pub alive: bool,
  231:     pub how: String,
  232: }
  233: 
  234: impl Verdict {
  235:     fn new(alive: bool, how: impl Into<String>) -> Verdict {
  236:         Verdict {
  237:             alive,
  238:             how: how.into(),
  239:         }
  240:     }
  241: }
  242: 
  243: /// (wave 28e, E1 / F54-1; E19 / F27-2) `Test-UnverifiedProcess`: a pid of the record's
  244: /// `unverified[]` - a descendant whose start time could not be read at the kill - checked again,
  245: /// FAIL-CLOSED on the evidence, in this order:
  246: ///   no such process - dropped (`gone`);
  247: ///   its start time STILL cannot be read - running (it blocks the task as a survivor does);
  248: ///   started before that run (`since`, the record's `started`) - dropped (not its process);
  249: ///   the "looks like codex" rule matches - running;
  250: ///   its command line cannot be read (`""` - access denied -, ps's `[name]`, or a generic runtime
  251: ///     such as node or powershell with nothing after the executable) - running (`command line not
  252: ///     readable - counted as running (fail-closed)`);
  253: ///   a child of a recorded pid (`recorded_pids`: the writer, the child, the survivors, the other
  254: ///     unverified pids) - running;
  255: ///   else - its command line was read and is not codex-like - dropped (`not codex`).
  256: /// Never by pid alone. The same rule re-checks a survivor recorded without a start time, or whose
  257: /// start time cannot be read now ([`test_recorded_process`]).
  258: pub fn test_unverified_process(
  259:     pid: u32,
  260:     since: Option<chrono::DateTime<chrono::Utc>>,
  261:     launcher: &str,
  262:     recorded_pids: &[u32],
  263: ) -> Verdict {
  264:     let Some(st) = proc::process_start_iso(pid) else {
  265:         return Verdict::new(false, "gone");
  266:     };
  267:     if st.is_empty() {
  268:         return Verdict::new(
  269:             true,
  270:             "its start time still cannot be read - counted as running (fail-closed)",
  271:         );
  272:     }
  273:     if let Some(since) = since {
  274:         if let Ok(at) = chrono::DateTime::parse_from_rfc3339(&st) {
  275:             if at.with_timezone(&chrono::Utc) < since {
  276:                 return Verdict::new(
  277:                     false,
  278:                     format!("started {st}, before that run: not its process"),
  279:                 );
  280:             }
  281:         }
  282:     }
  283:     let Some(info) = proc::process_info(pid) else {
  284:         return Verdict::new(false, "gone");
  285:     };
  286:     // (wave 29, E27) a codex-named server or helper of the Codex app is not codex-like; it still has
  287:     // to pass the command-line and parent checks below, and its drop says what it was taken for
  288:     let m = proc::codex_match(&info.name, &info.cmd, launcher);
  289:     if !m.rule.is_empty() {
  290:         return Verdict::new(true, format!("start time readable now; {}", m.rule));
  291:     }
  292:     let gap = proc::command_line_gap(&info.name, &info.cmd);
  293:     if !gap.is_empty() {
  294:         let generic = if gap == "no arguments" {
  295:             " (a generic runtime, no arguments on its command line)"
  296:         } else {
  297:             ""
  298:         };
  299:         return Verdict::new(
  300:             true,
  301:             format!(
  302:                 "start time readable now; pid {pid} runs {}{generic}; command line not readable - counted as running (fail-closed)",
  303:                 info.name
  304:             ),
  305:         );
  306:     }
  307:     if info.ppid > 0 && info.ppid != pid && recorded_pids.contains(&info.ppid) {
  308:         return Verdict::new(
  309:             true,
  310:             format!(
  311:                 "start time readable now; pid {pid} runs {}, a child of the recorded pid {} - counted as running",
  312:                 info.name, info.ppid
  313:             ),
  314:         );
  315:     }
  316:     let excluded = if m.excluded.is_empty() {
  317:         String::new()
  318:     } else {
  319:         format!(" (excluded: {})", m.excluded)
  320:     };
  321:     Verdict::new(
  322:         false,
  323:         format!(
  324:             "start time readable now; pid {pid} runs {}, not codex{excluded}",
  325:             info.name
  326:         ),
  327:     )
  328: }
  329: 
  330: /// `Test-RecordedProcess`: is a process recorded in a pending record still that process? With a
  331: /// recorded start time that can be read now too: alive only when the pid runs with that start time
  332: /// (and that name, when one is recorded) - another start time means the pid was reused. Without
  333: /// one (a bare pid, or `start_time` empty), or when the live start time cannot be read: (wave 28e,
  334: /// E19 / F27-2) the same fail-closed evidence rule and messages as an unverified pid
  335: /// ([`test_unverified_process`]).
  336: pub fn test_recorded_process(
  337:     pid: u32,
  338:     start_time: &str,
  339:     name: &str,
  340:     launcher: &str,
  341:     since: Option<chrono::DateTime<chrono::Utc>>,
  342:     recorded_pids: &[u32],
  343: ) -> Verdict {
  344:     let Some(info) = proc::process_info(pid) else {
  345:         return Verdict::new(false, "gone");
  346:     };
  347:     if !start_time.is_empty() && !info.start.is_empty() {
  348:         if !proc::same_start_time(&info.start, start_time) {
  349:             return Verdict::new(false, "pid reused (start time differs)");
  350:         }
  351:         if !name.is_empty() && !info.name.eq_ignore_ascii_case(name) {
  352:             return Verdict::new(false, format!("pid reused (now {})", info.name));
  353:         }
  354:         return Verdict::new(true, "pid + start time");
  355:     }
  356:     test_unverified_process(pid, since, launcher, recorded_pids)
  357: }
