  366:     since: chrono::DateTime<chrono::Utc>,
  367:     since_text: &str,
  368:     launcher: &str,
  369:     parent: u32,
  370:     on_windows: bool,
  371: ) -> proc::ScanOutcome {
  372:     let self_pid = std::process::id();
  373:     let procs = match table {
  374:         Ok(t) => t,
  375:         Err(e) => {
  376:             let mut s = proc::find_codex_processes(
  377:                 &[],
  378:                 since,
  379:                 since_text,
  380:                 launcher,
---CHUNK---
  410: 
  411: /// `Test-PendingActive`: whether a recovery record still belongs to a live consultation. The rules,
  412: /// in this order:
  413: ///   1. THE WRITER (wave 21, D1) decides first: a record that names the bridge that wrote it (pid +
  414: ///      start time) is active while that process runs on this host, in every state. Never by pid
  415: ///      alone, never this very process, not across hosts.
  416: ///   2. When the writer is gone or unknown, the state decides: `reserved` - inactive; `running`,
  417: ///      `survivors`, `committing` - active while `child_pid` (with its start time) or any survivor
  418: ///      is alive ([`test_recorded_process`]) or - (wave 28e, E1) - an unverified pid
  419: ///      ([`test_unverified_process`]); every one is named; pids from another host: active; all
  420: ///      recorded pids gone: the process scan below; `launching` - the scan below.
  421: ///      (wave 28e, E23 / F30-1; E25 / F32-1) a record with `kill_unconfirmed` (a kill that was not
  422: ///      confirmed and named no pid): its tree is unknown - released only by a clean scan by parent
  423: ///      pid (the writer, the child, every other recorded pid) AND the machine-wide rule, a panel
  424: ///      member's record too (a live sibling's reviewer merely postpones its release); a failed
  425: ///      scan, a find, a host outside Windows or another host: active.
  426: ///   3. The process scan: children of the recorded writer and pids (Windows keeps an orphan's
  427: ///      parent id), then - outside a panel only - the machine-wide "looks like codex" rule
  428: ///      (`Find-CodexProcesses`, "task not verifiable"). READ-ONLY: it never stops anything.
  429: pub fn test_pending_active(record: &Value, path: &Path) -> PendingCheck {
  430:     let state = pv_str(record, "state", "");
  431:     let rec_host = pv_str(record, "host", "");
  432:     let other_host = !rec_host.is_empty() && !rec_host.eq_ignore_ascii_case(&machine_name());
  433:     let mut what = format!(
  434:         "state '{}', consult n={}, handoff {}, started {}",
  435:         state,
  436:         pv_str(record, "n", "?"),
  437:         pv_str(record, "nn", "?"),
  438:         pv_str(record, "started", "?")
  439:     );
  440:     let is_panel = pv(record, "panel").is_some();
  441:     if let Some(panel) = pv(record, "panel") {
  442:         let id = pv_str(panel, "id", "");
  443:         let short: String = id.chars().take(8).collect();
  444:         what += &format!(
  445:             ", review panel {} member {}",
  446:             short,
  447:             pv_str(panel, "position", "?")
  448:         );
  449:     }
  450:     let cli = {
  451:         let e = pv_str(record, "engine", "");
  452:         if e.is_empty() {
  453:             "codex".to_string()
  454:         } else {
  455:             e
  456:         }
  457:     };
  458:     let launcher = pv_str(record, "launcher", "");
  459:     let started = pv_str(record, "started", "");
  460: 
  461:     // Recorded pids: child_pid, then survivors ({pid,start_time,name} or a bare pid).
  462:     struct Pid {
  463:         pid: u32,
  464:         start: String,
  465:         name: String,
  466:     }
  467:     let mut pids: Vec<Pid> = Vec::new();
  468:     if let Some(cp) = pv_i64(record, "child_pid") {
  469:         if cp > 0 {
  470:             pids.push(Pid {
  471:                 pid: cp as u32,
  472:                 start: pv_str(record, "child_start_time", ""),
  473:                 name: String::new(),
  474:             });
  475:         }
  476:     }
  477:     if let Some(Value::Array(survivors)) = pv(record, "survivors") {
  478:         for s in survivors {
  479:             if let Some(obj) = s.as_object() {
  480:                 if let Some(sp) = obj.get("pid").and_then(pv_num) {
  481:                     if sp > 0 {
  482:                         pids.push(Pid {
  483:                             pid: sp as u32,
  484:                             start: pv_str(s, "start_time", ""),
  485:                             name: pv_str(s, "name", ""),
  486:                         });
  487:                     }
  488:                 }
  489:             } else if let Some(sp) = pv_num(s) {
  490:                 if sp > 0 {
  491:                     pids.push(Pid {
  492:                         pid: sp as u32,
  493:                         start: String::new(),
  494:                         name: String::new(),
  495:                     });
  496:                 }
  497:             }
  498:         }
  499:     }
  500:     // (wave 28e, E1 / F54-1) unverified: {pid, why} entries - descendants whose start time could
  501:     // not be read at the kill; reported and checked again below
  502:     struct Unverified {
  503:         pid: u32,
  504:         why: String,
  505:     }
  506:     let mut unverified: Vec<Unverified> = Vec::new();
  507:     if let Some(Value::Array(list)) = pv(record, "unverified") {
  508:         for u in list {
  509:             if let Some(obj) = u.as_object() {
  510:                 if let Some(up) = obj.get("pid").and_then(pv_num) {
  511:                     if up > 0 {
  512:                         unverified.push(Unverified {
  513:                             pid: up as u32,
  514:                             why: pv_str(u, "why", ""),
  515:                         });
  516:                     }
  517:                 }
  518:             } else if let Some(up) = pv_num(u) {
  519:                 if up > 0 {
  520:                     unverified.push(Unverified {
  521:                         pid: up as u32,
  522:                         why: String::new(),
  523:                     });
  524:                 }
  525:             }
  526:         }
  527:     }
  528: 
  529:     let original_note = pending_original_note(record);
  530:     let inactive = |c: String| PendingCheck {
  531:         active: false,
  532:         message: String::new(),
  533:         check: if original_note.is_empty() {
  534:             c
  535:         } else {
  536:             format!("{c}; {original_note}")
  537:         },
  538:     };
  539:     let active = |m: String, c: String| PendingCheck {
  540:         active: true,
  541:         message: if original_note.is_empty() {
  542:             m
  543:         } else {
  544:             format!("{}; {}.", m.trim_end_matches('.'), original_note)
  545:         },
  546:         check: c,
  547:     };
  548: 
  549:     // D1: the bridge that wrote the record, while it runs â€” by pid + start time, never this
  550:     // process, never across hosts.
  551:     let writer_pid = pv_i64(record, "pid").unwrap_or(0);
  552:     let writer_start = pv_str(record, "start_time", "");
  553:     let mut writer_gone = String::new();
  554:     if writer_pid > 0 && !writer_start.is_empty() && writer_pid as u32 != std::process::id() {
  555:         if other_host {
  556:             // cannot be checked from here; the rules below decide.
  557:         } else if proc::pid_alive(writer_pid as u32, &writer_start) {
  558:             return active(
  559:                 format!(
  560:                     "a consultation of this task is still running: its bridge (pid {writer_pid}) wrote {} ({what}). Wait for it to finish; the record is removed when it commits.",
  561:                     path.display()
  562:                 ),
  563:                 format!("writer pid {writer_pid} alive (pid + start time)"),
  564:             );
  565:         } else {
  566:             writer_gone = format!("writer pid {writer_pid} gone");
  567:         }
  568:     }
  569: 
  570:     if state == "reserved" {
  571:         let suffix = if writer_gone.is_empty() {
  572:             String::new()
  573:         } else {
  574:             format!("; {writer_gone}")
  575:         };
  576:         return inactive(format!("reserved: {cli} was never started{suffix}"));
  577:     }
  578: 
  579:     // The record's start, for every re-check by the evidence rule and every scan: a process that
  580:     // started before the record is not its.
  581:     let started_at = chrono::DateTime::parse_from_rfc3339(&started)
  582:         .ok()
  583:         .map(|d| d.with_timezone(&chrono::Utc));
  584: 
  585:     let mut recorded_gone = String::new();
  586:     if (!pids.is_empty() || !unverified.is_empty()) && state != "launching" {
  587:         if other_host {
  588:             let pid_list = pids
  589:                 .iter()
  590:                 .map(|p| p.pid)
  591:                 .chain(unverified.iter().map(|u| u.pid))
  592:                 .map(|p| p.to_string())
  593:                 .collect::<Vec<_>>()
  594:                 .join(", ");
  595:             return active(
  596:                 format!(
  597:                     "an interrupted consultation on host {rec_host} left {cli} process(es) pid {pid_list} ({what}); they cannot be checked from this host. Delete {} only after making sure they are gone.",
  598:                     path.display()
  599:                 ),
  600:                 format!("pids on host {rec_host}"),
  601:             );
  602:         }
  603:         // (wave 28e, E19 / F27-2) the record's pids, for every re-check by the evidence rule: a
  604:         // child of a recorded pid is never dropped
  605:         let mut recorded_pids: Vec<u32> = Vec::new();
  606:         for p in std::iter::once(writer_pid.max(0) as u32)
  607:             .chain(pids.iter().map(|p| p.pid))
  608:             .chain(unverified.iter().map(|u| u.pid))
  609:         {
  610:             if p > 0 && !recorded_pids.contains(&p) {
  611:                 recorded_pids.push(p);
  612:             }
  613:         }
  614:         let mut alive: Vec<String> = Vec::new();
  615:         let mut alive_how: Vec<String> = Vec::new();
  616:         let mut gone: Vec<String> = Vec::new();
  617:         let mut seen: Vec<u32> = Vec::new();
  618:         for p in &pids {
  619:             // Dedup: the same pid can appear as both `child_pid` and a bare survivor.
  620:             if seen.contains(&p.pid) {
  621:                 continue;
  622:             }
  623:             seen.push(p.pid);
  624:             let v = test_recorded_process(
  625:                 p.pid,
  626:                 &p.start,
  627:                 &p.name,
  628:                 &launcher,
  629:                 started_at,
  630:                 &recorded_pids,
  631:             );
  632:             // (E19) a pid judged by the evidence rule (not by its pid + start time) says why
  633:             if v.alive {
  634:                 alive.push(if v.how == "pid + start time" {
  635:                     p.pid.to_string()
  636:                 } else {
  637:                     format!("{} [{}]", p.pid, v.how)
  638:                 });
  639:                 alive_how.push(format!("{} [{}]", p.pid, v.how));
  640:             } else {
  641:                 gone.push(format!("{} [{}]", p.pid, v.how));
  642:             }
  643:         }
  644:         // (wave 28e, E1 / F54-1) the descendants the kill could not verify, checked again now: one
  645:         // still unreadable, or readable and codex-like, blocks like a survivor; a gone one is
  646:         // dropped - said
  647:         let mut u_alive: Vec<String> = Vec::new();
  648:         let mut u_gone: Vec<String> = Vec::new();
  649:         for u in &unverified {
  650:             let v = test_unverified_process(u.pid, started_at, &launcher, &recorded_pids);
  651:             if v.alive {
  652:                 let at_kill = if u.why.is_empty() {
  653:                     String::new()
  654:                 } else {
  655:                     format!("; at the kill: {}", u.why)
  656:                 };
  657:                 u_alive.push(format!("{} [{}{at_kill}]", u.pid, v.how));
  658:             } else {
  659:                 u_gone.push(format!("{} [{}]", u.pid, v.how));
  660:             }
  661:         }
  662:         let u_dropped = if u_gone.is_empty() {
  663:             String::new()
  664:         } else {
  665:             format!("unverified pid(s) {} dropped", u_gone.join(", "))
  666:         };
  667:         if !alive.is_empty() || !u_alive.is_empty() {
  668:             let mut parts: Vec<String> = Vec::new();
  669:             let mut check_parts: Vec<String> = Vec::new();
  670:             if !alive.is_empty() {
  671:                 parts.push(format!(
  672:                     "a previous consultation's {cli} process (pid {}) is still running ({what})",
  673:                     alive.join(", ")
  674:                 ));
  675:                 check_parts.push(format!("pid {} alive", alive_how.join(", ")));
  676:             }
  677:             if !u_alive.is_empty() {
  678:                 parts.push(if !alive.is_empty() {
  679:                     format!(
  680:                         "a process its kill could not verify blocks too: pid {}",
  681:                         u_alive.join(", ")
  682:                     )
  683:                 } else {
  684:                     format!(
  685:                         "a previous consultation's {cli} run left a process its kill could not verify ({what}): pid {} - it blocks the task as a survivor does",
  686:                         u_alive.join(", ")
  687:                     )
  688:                 });
  689:                 check_parts.push(format!(
  690:                     "unverified pid {} counted as running",
  691:                     u_alive.join(", ")
  692:                 ));
  693:             }
  694:             if !u_dropped.is_empty() {
  695:                 parts.push(u_dropped.clone());
  696:                 check_parts.push(u_dropped.clone());
  697:             }
  698:             return active(
  699:                 format!(
  700:                     "{}. Wait for it to exit or stop it, then retry; {} keeps its record until then.",
  701:                     parts.join("; "),
  702:                     path.display()
  703:                 ),
  704:                 check_parts.join("; "),
  705:             );
  706:         }
  707:         // Every RECORDED pid is gone - but a dead launcher is no proof of a dead tree: the
  708:         // descendant scan below decides (F04-10).
  709:         let mut gone_parts: Vec<String> = Vec::new();
  710:         if !gone.is_empty() {
  711:             gone_parts.push(format!(
  712:                 "{cli} pid(s) {} no longer running",
  713:                 gone.join(", ")
  714:             ));
  715:         }
  716:         if !u_dropped.is_empty() {
  717:             gone_parts.push(u_dropped);
  718:         }
  719:         recorded_gone = gone_parts.join("; ");
  720:     }
  721:     if !writer_gone.is_empty() {
  722:         recorded_gone = if recorded_gone.is_empty() {
  723:             writer_gone.clone()
  724:         } else {
  725:             format!("{writer_gone}; {recorded_gone}")
  726:         };
  727:     }
  728: 
  729:     let on_windows = cfg!(windows);
  730:     // The scans' start: `started` (no usable start: no age cut-off - everything counts, as the
  731:     // plugin's MinValue does), and its local stamp for the messages.
  732:     let since =
  733:         started_at.unwrap_or_else(|| chrono::DateTime::from_timestamp(0, 0).unwrap_or_default());
  734:     let since_text = since
  735:         .with_timezone(&chrono::Local)
  736:         .format("%Y-%m-%dT%H:%M:%S")
  737:         .to_string();
  738:     // Parent pids whose (orphaned) children would be ours: the bridge that wrote the record, every
  739:     // recorded pid (the launcher shim, the survivors) and (wave 28e, E1) every unverified pid. On
  740:     // Windows an orphan keeps its dead parent's pid; elsewhere only the command-line rule finds it.
  741:     let mut parent_pids: Vec<u32> = Vec::new();
  742:     if writer_pid > 0 {
  743:         parent_pids.push(writer_pid as u32);
  744:     }
  745:     for p in pids
  746:         .iter()
  747:         .map(|p| p.pid)
  748:         .chain(unverified.iter().map(|u| u.pid))
  749:     {
  750:         if p > 0 && !parent_pids.contains(&p) {
  751:             parent_pids.push(p);
  752:         }
  753:     }
  754: 
  755:     // (wave 28e, E23 / F30-1; E25 / F32-1) a kill that was not confirmed and named no pid left an
  756:     // UNKNOWN tree: only a clean scan by parent pid AND a clean machine-wide check release it.
