  849: /// [`descendants_of`] over a given process table (pure): every row is visited at most once, so
  850: /// the walk is bounded by the table itself and never truncates (F09-4).
  851: pub fn descendants_in(procs: &[ScanProc], pid: u32) -> Vec<u32> {
  852:     let mut seen: std::collections::HashSet<u32> = std::collections::HashSet::new();
  853:     seen.insert(pid);
  854:     let mut out = Vec::new();
  855:     let mut frontier = vec![pid];
  856:     while let Some(parent) = frontier.pop() {
  857:         for p in procs.iter().filter(|p| p.ppid == parent) {
  858:             if seen.insert(p.pid) {
  859:                 out.push(p.pid);
  860:                 frontier.push(p.pid);
  861:             }
  862:         }
  863:     }
  864:     out
  865: }
