 fn go_duration_seconds(text: &str) -> Option<f64> {
     let re = Regex::new(r"(?i)(?P<n>[0-9]+(?:\.[0-9]+)?)\s*(?P<u>ms|hours?|hrs?|h|minutes?|mins?|m|seconds?|secs?|s)").unwrap();
     let mut total = 0.0;
