     for c in re.captures_iter(text) {
         let n: f64 = c["n"].parse().ok()?;
         let u = c["u"].to_lowercase();
         if u == "ms" {
             total += n / 1000.0;
         } else if u.starts_with('h') {
             total += n * 3600.0;
         } else if u.starts_with('m') {
             total += n * 60.0;
         } else {
             total += n;
         }
         any = true;
     }
     if any {
         Some(total)
     } else {
         None
     }
 }

 fn compact_duration_seconds(text: &str) -> Option<f64> {
     let re = Regex::new(r"(?i)(?P<n>[0-9]+(?:\.[0-9]+)?)(?P<u>w|d|h|ms|m|s)").unwrap();
     let mut total = 0.0;
     let mut any = false;
     for c in re.captures_iter(text) {
         let n: f64 = c["n"].parse().ok()?;
         match c["u"].to_lowercase().as_str() {
             "w" => total += n * 604800.0,
             "d" => total += n * 86400.0,
             "h" => total += n * 3600.0,
             "m" => total += n * 60.0,
             "ms" => total += n / 1000.0,
             _ => total += n,
         }
         any = true;
     }
     if any {
         Some(total)
     } else {
         None
     }
 }

