 85:     use std::time::{Duration, Instant};
 86: 
 87:     use c3::engines::subprocess::{run_turn, SpawnRequest, TurnResult, TurnStop};
 88:     use c3::liveness::proc;
 89:     use c3_core::engine::PromptDelivery;
 90: 
 91:     use super::{set, unset};
 92: 
 93:     fn scratch_dir(tag: &str) -> std::path::PathBuf {
 94:         let d = std::env::temp_dir().join(format!("c3-w3a-{tag}-{}", std::process::id()));
 95:         let _ = std::fs::remove_dir_all(&d);
 96:         std::fs::create_dir_all(&d).unwrap();
 97:         d
 98:     }
 99: 
100:     /// The first descendant of `root` (the batch file's `ping`), waited for up to 5 s.
101:     fn first_descendant(root: u32) -> u32 {
102:         let until = Instant::now() + Duration::from_secs(5);
103:         loop {
104:             if let Some(d) = proc::descendants_of(root).first() {
105:                 return *d;
106:             }
107:             if Instant::now() >= until {
108:                 return 0;
109:             }
110:             std::thread::sleep(Duration::from_millis(50));
111:         }
112:     }
113: 
114:     /// One turn of a `.cmd` that hangs (`cmd.exe` -> `PING.EXE`), killed on a 1 s timeout;
115:     /// `on_child(root, child)` runs once the child exists, before the wait begins.
116:     fn hanging_turn(tag: &str, on_child: &dyn Fn(u32, u32)) -> (TurnResult, u32, u32) {
117:         let dir = scratch_dir(tag);
118:         let launcher = dir.join("hang.cmd");
119:         std::fs::write(&launcher, "@echo off\r\nping 127.0.0.1 -n 30 >nul\r\n").unwrap();
120:         let events = dir.join("out.jsonl");
121:         let stderr = dir.join("err.txt");
122:         let root = AtomicU32::new(0);
123:         let child = AtomicU32::new(0);
124:         let cb = |pid: u32, _start: String| {
125:             root.store(pid, Ordering::SeqCst);
126:             let c = first_descendant(pid);
127:             child.store(c, Ordering::SeqCst);
128:             on_child(pid, c);
129:         };
130:         let req = SpawnRequest {
131:             launcher: launcher.to_str().unwrap(),
132:             argv: &[],
133:             cwd: &dir,
134:             prompt_delivery: PromptDelivery::Stdin,
135:             stdin_text: "",
136:             events_path: &events,
137:             stderr_path: &stderr,
138:             timeout: Duration::from_secs(1),
139:             stall_sec: 0,
140:             kick_path: None,
141:             tool_flight: None,
142:             on_running: Some(&cb),
143:         };
144:         let result = run_turn(&req);
145:         assert!(matches!(result.stop, TurnStop::Timeout), "{tag}: timed out");
146:         let _ = std::fs::remove_dir_all(dir);
147:         (
148:             result,
149:             root.load(Ordering::SeqCst),
150:             child.load(Ordering::SeqCst),
151:         )
152:     }
