161:         set("CODEX_CONSULT_TEST_MODE", "1");
162: 
163:         // (a) a clean tree kill: the root and its child gone - confirmed, nothing named
164:         let (r, root, child) = hanging_turn("clean", &|_, _| {});
165:         let k = r.kill.clone().expect("a kill check");
166:         assert!(child > 0, "the batch file started its child");
167:         assert!(
