/// (a Linux `/proc/<pid>/comm` such as `日本`) is returned unchanged instead of panicking.
fn strip_exe(name: &str) -> &str {
    let cut = name.len().saturating_sub(4);
    match name.get(cut..) {
        Some(tail) if tail.eq_ignore_ascii_case(".exe") => &name[..cut],
