695: /// "started at or after" stamp for the message; `since` is the same instant for the comparison.
696: /// With a bridge pid on Windows, a process counts when its parent is that pid and it started at or
697: /// after `since` (and, if the pid was reused by a live process, before that reuse). Otherwise the
698: /// machine-wide "looks like codex" rule applies (labelled "task not verifiable"); (wave 29, E27) the
699: /// Codex desktop app's servers and helpers ([`codex_server_exclusion`]) are left out and named in
700: /// `check` ("excluded: pid N codex.exe [codex app-server]", at most 6, then "(+k more)") and in
701: /// `excluded`. This process and its ancestors are never counted.
702: #[allow(clippy::too_many_arguments)]
703: pub fn find_codex_processes(
704:     procs: &[ScanProc],
705:     since: chrono::DateTime<chrono::Utc>,
706:     since_text: &str,
707:     launcher: &str,
708:     bridge_pid: u32,
709:     self_pid: u32,
710:     on_windows: bool,
711: ) -> ScanOutcome {
712:     let by_parent = on_windows && bridge_pid > 0;
713:     let rules = if by_parent {
714:         format!("children of the interrupted bridge pid {bridge_pid}")
715:     } else {
716:         "name codex*, or a command line containing the recorded launcher or @openai/codex; not the Codex app's servers and helpers"
