726:     use std::collections::{HashMap, HashSet};
727:     let by_id: HashMap<u32, &ScanProc> = procs.iter().map(|p| (p.pid, p)).collect();
728:     // Never count ourselves or our ancestors (a shell that started this run may carry the launcher
729:     // path on its command line).
